    private static readonly Dictionary<string, float> _base_element_resistances = new()
    {
        ["OCS"]  = 0.001f,   // TODO substation and contact wire
        ["PANT"] = 0.01f,    // TODO pantograph contact
        ["I1"]   = 0.008f * resistor_scale,   // inductive shunt, DC resistance (303E DTR), motors 1 and 2
        ["I2"]   = 0.008f * resistor_scale,   // motors 3 and 4
    };

    // ---- scale: 1500 V line, 1500 kW ----------------------------------------------------
    // real: 2000 kW on 3000 V; motors wound for half volts (speeds real), more amps
    // (~500 A continuous vs 355 A real), 3/4 power and effort. Change only these two.
    public const float line_voltage_ratio = 1500f / 3000f;
    public const float power_ratio        = 1500f / 2000f;
    public const float current_ratio      = power_ratio / line_voltage_ratio;      // 1.5
    public const float resistor_scale     = line_voltage_ratio / current_ratio;    // 0.333

    // R1..R30 at 3000 V: designed, not documented (design_resistors.py, starting_resistors.json).
    // equal current peaks per notch; mean start effort 244 kN (DTR), under the 600 A relays
    private static readonly float[] _starting_resistors_3kV =
    {
        5.0295f, 3.8116f, 1.4443f, 1.4443f, 1.0946f, 1.0946f, 0.8296f, 0.8296f, 0.2338f, 0.2338f, 0.2177f, 0.2177f, 0.2026f, 0.2026f, 0.1886f, 0.1886f, 0.1756f, 0.1756f, 0.1635f, 0.1635f, 0.1522f, 0.1522f, 0.1417f, 0.1417f, 0.1319f, 0.1319f, 0.3544f, 0.3544f, 0.3544f, 0.3544f
    };

    // field left at the six weakening steps (303E DTR, primary)
    private static readonly float[] _field_fraction = { 0.755f, 0.582f, 0.435f, 0.347f, 0.280f, 0.220f };

    static eu07_sim()
    {
        for (int n = 1; n <= 30; ++n)
            _base_element_resistances[$"R{n}"] = _starting_resistors_3kV[n - 1] * resistor_scale;

        // shunts derived: leave the DTR's field-current fraction in this motor model
        // (pair's fields in series; steps in parallel; inductive shunt in series with all)
        float pair_field = 2.0f * eu07_traction_motor.internal_resistance * (1.0f - eu07_traction_motor.armature_part);
        float inductive  = _base_element_resistances["I1"];
        float previous_conductance = 0.0f;
        for (int step = 1; step <= 6; ++step)
        {
            float f = _field_fraction[step - 1];
            float shunt_total = f * pair_field / (1.0f - f);
            float conductance = 1.0f / Mathf.Max(shunt_total - inductive, 1e-4f);
            float branch = 1.0f / Mathf.Max(conductance - previous_conductance, 1e-4f);
            _base_element_resistances[$"RP{2 * step - 1}"] = branch;      // motors 1 and 2
            _base_element_resistances[$"RP{2 * step}"]     = branch;      // motors 3 and 4
            previous_conductance = conductance;
        }

        for (int m = 1; m <= motors; ++m)
        {
            // Knsgf's partitioning: armature branch, field in two parts
            _base_element_resistances[$"MA{m}"]  = eu07_traction_motor.internal_resistance *         eu07_traction_motor.armature_part;
            _base_element_resistances[$"MF{m}a"] = eu07_traction_motor.internal_resistance * (1.0f - eu07_traction_motor.armature_part) * (1.0f - eu07_traction_motor.field_partitioning);
            _base_element_resistances[$"MF{m}b"] = eu07_traction_motor.internal_resistance * (1.0f - eu07_traction_motor.armature_part) * (       eu07_traction_motor.field_partitioning);
        }
    }
